-- AN24 ONE · Esquema inicial para Supabase/PostgreSQL
create extension if not exists "uuid-ossp";
create table if not exists profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, role text default 'commercial', phone text, avatar_url text, active boolean default true, created_at timestamptz default now());
create table if not exists clients (id uuid primary key default uuid_generate_v4(), code text unique, name text not null, legal_name text, tax_id text, client_type text default 'company', status text default 'active', email text, phone text, address text, city text, postal_code text, assigned_to uuid references profiles(id), notes text, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists contacts (id uuid primary key default uuid_generate_v4(), client_id uuid references clients(id) on delete cascade, full_name text not null, position text, email text, phone text, is_primary boolean default false, created_at timestamptz default now());
create table if not exists services (id uuid primary key default uuid_generate_v4(), name text not null, category text not null, provider text, active boolean default true, created_at timestamptz default now());
create table if not exists contracts (id uuid primary key default uuid_generate_v4(), client_id uuid references clients(id) on delete cascade, service_id uuid references services(id), provider text, status text default 'active', start_date date, end_date date, monthly_value numeric(12,2), external_reference text, assigned_to uuid references profiles(id), created_at timestamptz default now());
create table if not exists opportunities (id uuid primary key default uuid_generate_v4(), client_id uuid references clients(id) on delete cascade, title text not null, service_id uuid references services(id), stage text default 'prospecting', value numeric(12,2) default 0, probability integer default 10, expected_close date, assigned_to uuid references profiles(id), notes text, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists tasks (id uuid primary key default uuid_generate_v4(), client_id uuid references clients(id) on delete cascade, opportunity_id uuid references opportunities(id) on delete set null, title text not null, description text, task_type text default 'follow_up', priority text default 'normal', status text default 'pending', due_at timestamptz, assigned_to uuid references profiles(id), created_by uuid references profiles(id), created_at timestamptz default now());
create table if not exists activities (id uuid primary key default uuid_generate_v4(), client_id uuid references clients(id) on delete cascade, opportunity_id uuid references opportunities(id) on delete set null, activity_type text not null, subject text not null, description text, performed_by uuid references profiles(id), performed_at timestamptz default now());
create table if not exists documents (id uuid primary key default uuid_generate_v4(), client_id uuid references clients(id) on delete cascade, opportunity_id uuid references opportunities(id) on delete set null, name text not null, document_type text, storage_path text not null, mime_type text, size_bytes bigint, uploaded_by uuid references profiles(id), created_at timestamptz default now());
alter table profiles enable row level security; alter table clients enable row level security; alter table contacts enable row level security; alter table contracts enable row level security; alter table opportunities enable row level security; alter table tasks enable row level security; alter table activities enable row level security; alter table documents enable row level security;
create policy "Authenticated users read profiles" on profiles for select to authenticated using (true);
create policy "Authenticated users manage clients" on clients for all to authenticated using (true) with check (true);
create policy "Authenticated users manage contacts" on contacts for all to authenticated using (true) with check (true);
create policy "Authenticated users manage contracts" on contracts for all to authenticated using (true) with check (true);
create policy "Authenticated users manage opportunities" on opportunities for all to authenticated using (true) with check (true);
create policy "Authenticated users manage tasks" on tasks for all to authenticated using (true) with check (true);
create policy "Authenticated users manage activities" on activities for all to authenticated using (true) with check (true);
create policy "Authenticated users manage documents" on documents for all to authenticated using (true) with check (true);
